import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int rows = Integer.parseInt(fs.next());
        int cols = Integer.parseInt(fs.next());

        int variableCount = 26 * 26;
        int equationCount = rows + cols;
        int[][] coefficients = new int[equationCount][variableCount];
        long[] remaining = new long[equationCount];
        int[] unknownCount = new int[equationCount];
        boolean[] present = new boolean[variableCount];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                String name = fs.next();
                int id = (name.charAt(0) - 'a') * 26 + name.charAt(1) - 'a';
                coefficients[r][id]++;
                present[id] = true;
            }
            remaining[r] = fs.nextLong();
        }

        for (int c = 0; c < cols; c++) {
            remaining[rows + c] = fs.nextLong();
        }

        for (int e = 0; e < equationCount; e++) {
            for (int v = 0; v < variableCount; v++) {
                if (coefficients[e][v] > 0) unknownCount[e]++;
            }
        }

        ArrayDeque<Integer> queue = new ArrayDeque<>();
        for (int e = 0; e < equationCount; e++) {
            if (unknownCount[e] == 1) queue.add(e);
        }

        boolean[] known = new boolean[variableCount];
        long[] value = new long[variableCount];

        while (!queue.isEmpty()) {
            int e = queue.poll();
            if (unknownCount[e] != 1) continue;

            int variable = -1;
            for (int v = 0; v < variableCount; v++) {
                if (coefficients[e][v] > 0 && !known[v]) {
                    variable = v;
                    break;
                }
            }
            if (variable == -1) continue;

            int coefficient = coefficients[e][variable];
            long solvedValue = remaining[e] / coefficient;
            known[variable] = true;
            value[variable] = solvedValue;

            for (int other = 0; other < equationCount; other++) {
                int count = coefficients[other][variable];
                if (count == 0) continue;

                remaining[other] -= count * solvedValue;
                unknownCount[other]--;
                if (unknownCount[other] == 1) queue.add(other);
            }
        }

        StringBuilder output = new StringBuilder();
        for (int v = 0; v < variableCount; v++) {
            if (present[v]) {
                output.append((char) ('a' + v / 26))
                      .append((char) ('a' + v % 26))
                      .append(' ')
                      .append(value[v])
                      .append('\n');
            }
        }
        System.out.print(output);
    }
}
